import numpy as np


def is_psd(H, tol=1e-12):
    return bool(np.linalg.eigvalsh(np.array(H, dtype=float)).min() >= -tol)


def numerical_hessian(f, x, h=1e-4):
    x = np.array(x, dtype=float)
    n = len(x)
    H = np.zeros((n, n))
    E = np.eye(n) * h
    for i in range(n):
        for j in range(n):
            H[i, j] = (f(x + E[i] + E[j]) - f(x + E[i] - E[j])
                       - f(x - E[i] + E[j]) + f(x - E[i] - E[j])) / (4 * h * h)
    return (H + H.T) / 2


def convex_at(f, x, tol=1e-6):
    return is_psd(numerical_hessian(f, x), tol)
